def count_paths(n, edges, start, finish):
    graph = [[] for _ in range(n)]
    for left, right in edges:
        graph[left].append(right)
    memo = {}
    def visit(vertex):
        if vertex == finish:
            return 1
        if vertex not in memo:
            memo[vertex] = sum(visit(neighbour) for neighbour in graph[vertex])
        return memo[vertex]
    return visit(start)
